-- ÜRETİLDİ, elle düzenlemeyin
/* ==========================================================================
   T07 — KVKK metin sürümleri

   Üreten: tools/vt/tohum-uret.mjs (npm run vt -- tohum). Bu dosyayı elle
   düzenlemeyin: kaynak değişince yeniden üretilir ve el değişikliği
   kaybolur. Kaynağı değiştirin, sonra "npm run vt -- tohum" çalıştırın.

   6 metin satırı (sürüm 1.0, 2026-08-14).

   Kaynak: src/data/kvkk.js (METINLER, KVKK_SURUM, KVKK_TARIH), src/data/kvkk.en.js
   (metinDilde ile). IcerikJson: metnin başlık dışındaki bölümleri, şirket
   bilgileri yerleşmiş hâliyle; IcerikOzeti: o JSON metninin UTF-8 SHA-256 özeti.
   Tasarım: tasarim.md 5.2 T07.

   Yalnız ekleme: var olan sürümün içeriği değişmişse betik durur (sürümü
   artırın). MERGE yazılmaz: kvkk.MetinSurumu INSTEAD OF tetikleyicilidir.
   Hukuk onayı kaynakta yok; HukukOnayiZamani boş kalır.

   Araç betiği tek işlemde, sahip girişiyle çalıştırır (BEGIN/COMMIT
   burada yazılmaz). İkinci çalıştırmada hiçbir satır değişmez.
   ========================================================================== */

/* kvkk.MetinSurumu — aynı sürüm numarasıyla farklı içerik: dur */
IF EXISTS (
    SELECT 1
    FROM kvkk.MetinSurumu AS h
    JOIN (VALUES
        (N'acikRiza', N'1.0', N'en', 0x757FE8B56298C22D2F9028450CEEBF5F81AE9EE3887FC8033EDDCDE8B6FE4C56),
        (N'acikRiza', N'1.0', N'tr', 0x1EEE9942FB970320133919ED057E2CE5262C0335DE6C9F8CCFB779BEFA61152E),
        (N'aydinlatma', N'1.0', N'en', 0x8C21E1A9802FA2F37BD69049CF6B425CFC3D94A7C8FF979B6623B39BCDE16A38),
        (N'aydinlatma', N'1.0', N'tr', 0xD86B46BA71FB08B71096268961264C3AE006E3613272A3602FF6F1F53B215BA2),
        (N'ticariIleti', N'1.0', N'en', 0xE2547319874ABED97729BCC609860A84C545B5C1C7167C482AD2BDA816D75E53),
        (N'ticariIleti', N'1.0', N'tr', 0x485DD09C796005F7EB9FC8F02A26607E3CCC4C2D661B66FC31B98C23E48133C6)
    ) AS k (MetinKodu, Surum, DilKodu, IcerikOzeti)
      ON h.MetinKodu = k.MetinKodu AND h.Surum = k.Surum AND h.DilKodu = k.DilKodu
    WHERE h.IcerikOzeti <> CONVERT(binary(32), k.IcerikOzeti)
)
    THROW 50003, N'<Codex metni: KVKK metninin içeriği değişmiş ama sürüm numarası aynı. src/data/kvkk.js içindeki KVKK_SURUM değerini artırın.>', 1;

/* kvkk.MetinSurumu — 6 satır, yalnız eksikler eklenir */

INSERT INTO kvkk.MetinSurumu (MetinKodu, Surum, DilKodu, Baslik, IcerikJson, IcerikOzeti, AsilMetin, MetinTarihi)
SELECT k.MetinKodu, k.Surum, k.DilKodu, k.Baslik, k.IcerikJson, k.IcerikOzeti, k.AsilMetin, k.MetinTarihi
FROM (
    SELECT CONVERT(nvarchar(40), v.MetinKodu) AS MetinKodu,
           CONVERT(nvarchar(10), v.Surum) AS Surum,
           CONVERT(nvarchar(5), v.DilKodu) AS DilKodu,
           CONVERT(nvarchar(200), v.Baslik) AS Baslik,
           CONVERT(nvarchar(max), v.IcerikJson) AS IcerikJson,
           CONVERT(binary(32), v.IcerikOzeti) AS IcerikOzeti,
           CONVERT(bit, v.AsilMetin) AS AsilMetin,
           CONVERT(date, v.MetinTarihi) AS MetinTarihi
    FROM (VALUES
        (N'acikRiza', N'1.0', N'en', N'Consent Statement', N'{"kisaAd":"Consent Statement","onayCumlesi":"I have read the Consent Statement and give my explicit consent to my personal data being processed within this scope and transferred to the authorised dealer / service.","bolumler":[{"baslik":"What are you consenting to?","paragraflar":["I confirm that I have read the Privacy Notice, and I give my explicit consent to my first and last name, mobile telephone number, province, the serial number of the machine I register and the content of the requests I create being processed by PAKSAN Makina for the purpose of carrying out after-sales support, service, spare parts and warranty processes."]},{"baslik":"Transfer to dealer and service","paragraflar":["When I create a service, spare part or quote request, I give my explicit consent to my name, telephone number, location (province / district) and machine serial number being transferred to the authorised dealer and authorised service nearest to me, so that my request can be met."]},{"baslik":"Contacting you","paragraflar":["I consent to PAKSAN, or the authorised service it directs, contacting me by telephone, SMS and app notification about the requests I have created.","Notifications in this scope relate solely to the service: that my request has been received, a service appointment, a safety warning about my machine and the like. Campaign and announcement notifications are not included; those require separate permission."]},{"baslik":"You can withdraw your consent","paragraflar":["You can withdraw this consent at any time. It is enough to write to paksan@paksanmakina.com.tr. When you withdraw your consent, actions taken up to the date of withdrawal remain valid."]}],"ustNot":"This is an English translation provided for convenience. The binding text is the Turkish original, prepared under Turkish Personal Data Protection Law No. 6698 (KVKK)."}', 0x757FE8B56298C22D2F9028450CEEBF5F81AE9EE3887FC8033EDDCDE8B6FE4C56, 0, N'2026-08-14'),
        (N'acikRiza', N'1.0', N'tr', N'Açık Rıza Metni', N'{"kisaAd":"Açık Rıza Metni","onayCumlesi":"Açık Rıza Metni’ni okudum, kişisel verilerimin bu kapsamda işlenmesine ve yetkili bayi/servise aktarılmasına açık rıza veriyorum.","bolumler":[{"baslik":"Neye rıza veriyorsunuz?","paragraflar":["Aydınlatma Metni’ni okuduğumu; ad soyad, cep telefonu numaram, ilim, kaydettiğim makinenin seri numarası ve oluşturduğum taleplerin içeriğinin PAKSAN Makina tarafından satış sonrası destek, servis, yedek parça ve garanti süreçlerinin yürütülmesi amacıyla işlenmesine açık rıza veriyorum."]},{"baslik":"Bayi ve servise aktarım","paragraflar":["Servis, yedek parça veya fiyat teklifi talebi oluşturduğumda; talebimin karşılanabilmesi için ad soyadımın, telefon numaramın, konum bilgimin (il/ilçe) ve makinemin seri numarasının bana en yakın yetkili bayi ve yetkili servise aktarılmasına açık rıza veriyorum."]},{"baslik":"Sizinle iletişim","paragraflar":["Oluşturduğum taleplerle ilgili olarak PAKSAN’ın veya yönlendirdiği yetkili servisin telefon, SMS ve uygulama bildirimi yoluyla benimle iletişime geçmesine rıza veriyorum.","Bu kapsamdaki bildirimler yalnızca hizmete ilişkindir: talebimin alındığı, servis randevusu, makinemle ilgili güvenlik uyarısı gibi. Kampanya ve duyuru bildirimleri buna dâhil değildir; onlar için ayrıca izin verilmesi gerekir."]},{"baslik":"Rızanızı geri alabilirsiniz","paragraflar":["Bu rızayı dilediğiniz zaman geri alabilirsiniz. paksan@paksanmakina.com.tr adresine yazmanız yeterlidir. Rızanızı geri aldığınızda, geri alma tarihine kadar yapılmış işlemler geçerliliğini korur."]}]}', 0x1EEE9942FB970320133919ED057E2CE5262C0335DE6C9F8CCFB779BEFA61152E, 1, N'2026-08-14'),
        (N'aydinlatma', N'1.0', N'en', N'Privacy Notice', N'{"kisaAd":"Privacy Notice","onayCumlesi":"I have read and understood the Privacy Notice.","bolumler":[{"baslik":"Who is the data controller?","paragraflar":["Your personal data is processed by PAKSAN MAKİNA SANAYİ VE TİCARET A.Ş. as data controller, within the scope described below, under Turkish Personal Data Protection Law No. 6698 (KVKK).","Address: Bandırma – Bursa Karayolu 10. km, Bandırma / Balıkesir","Address: Taştepe, Deri Organize Sanayi Bölgesi, 10900 Gönen / Balıkesir","Telephone: 444 9 725 · +90 266 733 90 90 · Fax: +90 266 733 90 99","E-mail: paksan@paksanmakina.com.tr"]},{"baslik":"Which of your data is processed?","maddeler":["Identity and contact details: first and last name, mobile telephone number","Location: the province you live in, and the district or village you enter when creating a request","Current position: only when you use the “find my nearest dealer” feature, and only inside your phone","Product details: the serial number, model and year of the machine you register","Request details: what you write in your service, spare part and quote requests","Invoice and delivery details: for spare part orders, the name of the person or company the invoice is issued to, national ID or tax number, delivery address and the payment receipt you upload","Support records: the questions you put to the support assistant and the answers given","Notification details: if you allow app notifications, the device notification token that lets the notification reach your phone"]},{"baslik":"For what purpose is it processed?","maddeler":["To provide technical and breakdown support for the machine you bought","To handle your service and spare part requests and route you to the right team","To run warranty processes and assess warranty cover","To show you the nearest authorised dealer and service point","To inform you if a product safety issue arises","To answer your quote requests","To issue the invoice for your spare part order, verify your payment and ship the part to the address you give","To send an app notification when the status of your request changes","And, if you allow it, to send you our campaigns and announcements by app notification"]},{"baslik":"What is the legal basis?","paragraflar":["Your data is processed on the following grounds set out in Article 5 of the KVKK:"],"maddeler":["Being directly related to the establishment or performance of a contract (after-sales service and warranty) — Art. 5/2-c","Compliance with the data controller’s legal obligation (warranty, consumer and tax legislation; the obligation to issue an invoice) — Art. 5/2-ç","Legitimate interest, provided it does not harm your fundamental rights and freedoms — Art. 5/2-f","Your explicit consent for transfer to authorised dealers and service points, and for the processing you consent to — Art. 5/1"]},{"baslik":"Who is it shared with?","paragraflar":["As far as necessary to meet your request, it may be transferred to your nearest authorised dealer and authorised service. For example, in a service request your name, telephone number and machine serial number are passed to the relevant service point.","Beyond that, transfers may be made to legally authorised public bodies where legislation requires it.","Your data is not sold or rented to third parties for marketing purposes."]},{"baslik":"How do we collect it?","paragraflar":["Your data is collected electronically, from what you enter into the app yourself. The app does not collect anything on its own that you have not entered.","Your current position is taken only when you press the “Use my location” button, is used only inside your phone to sort the nearest dealers, and is not sent anywhere.","The device notification token is created only when you allow app notifications. You can withdraw the permission at any time in your phone settings; once withdrawn, notifications cannot be sent."]},{"baslik":"How long is it kept?","paragraflar":["Your data is kept for as long as the after-sales service relationship continues and for the limitation periods required by the relevant legislation. At the end of that period it is deleted, destroyed or anonymised."]},{"baslik":"What are your rights?","paragraflar":["Under Article 11 of the KVKK you may request the following:"],"maddeler":["To learn whether your personal data is being processed, and if so to request information about it","To learn the purpose of processing and whether it is used in line with that purpose","To know the third parties to whom it is transferred, in Türkiye or abroad","To have it corrected if it is incomplete or inaccurate","To have it deleted or destroyed where the conditions are met","To have corrections and deletions notified to the third parties it was transferred to","To object to a result reached against you solely through automated analysis","To claim compensation if you suffer loss because of unlawful processing"]},{"baslik":"How do you apply?","paragraflar":["For the rights above you can write to paksan@paksanmakina.com.tr. Your application is concluded within 30 days at the latest.","If you want your account and records deleted completely, it is enough to write to the same address; the work is carried out by PAKSAN."]}],"ustNot":"This is an English translation provided for convenience. The binding text is the Turkish original, prepared under Turkish Personal Data Protection Law No. 6698 (KVKK)."}', 0x8C21E1A9802FA2F37BD69049CF6B425CFC3D94A7C8FF979B6623B39BCDE16A38, 0, N'2026-08-14'),
        (N'aydinlatma', N'1.0', N'tr', N'KVKK Aydınlatma Metni', N'{"kisaAd":"Aydınlatma Metni","onayCumlesi":"Aydınlatma Metni’ni okudum ve anladım.","bolumler":[{"baslik":"Veri sorumlusu kim?","paragraflar":["Kişisel verileriniz, 6698 sayılı Kişisel Verilerin Korunması Kanunu (KVKK) kapsamında veri sorumlusu sıfatıyla PAKSAN MAKİNA SANAYİ VE TİCARET A.Ş. tarafından, aşağıda açıklanan kapsamda işlenmektedir.","Adres: Bandırma – Bursa Karayolu 10. km, Bandırma / Balıkesir","Adres: Taştepe, Deri Organize Sanayi Bölgesi, 10900 Gönen / Balıkesir","Telefon: 444 9 725 · +90 266 733 90 90 · Faks: +90 266 733 90 99","E-posta: paksan@paksanmakina.com.tr"]},{"baslik":"Hangi verileriniz işleniyor?","maddeler":["Kimlik ve iletişim bilgisi: ad soyad, cep telefonu numarası","Konum bilgisi: yaşadığınız il, talep oluştururken yazdığınız ilçe/köy","Anlık konum: yalnızca \"size en yakın bayiyi bul\" özelliğini kullandığınızda, yalnızca telefonunuzun içinde","Ürün bilgisi: kaydettiğiniz makinenin seri numarası, modeli ve üretim yılı","Talep bilgisi: servis, yedek parça ve fiyat teklifi taleplerinizde yazdıklarınız","Fatura ve teslimat bilgisi: yedek parça siparişinde faturanın kesileceği kişi/firma adı, T.C. kimlik numarası veya vergi numarası, teslimat adresi ve yüklediğiniz ödeme dekontu","Destek kayıtları: destek asistanına yazdığınız sorular ve verilen cevaplar","Bildirim bilgisi: uygulama bildirimlerine izin verirseniz, bildirimin telefonunuza ulaşmasını sağlayan cihaz bildirim kimliği"]},{"baslik":"Ne amaçla işleniyor?","maddeler":["Satın aldığınız makineye teknik destek ve arıza desteği verebilmek","Servis ve yedek parça taleplerinizi karşılamak, sizi doğru ekibe yönlendirmek","Garanti süreçlerini yürütmek ve garanti kapsamını değerlendirmek","Size en yakın yetkili bayi ve servisi gösterebilmek","Ürün güvenliğiyle ilgili bir durum çıkarsa sizi bilgilendirebilmek","Fiyat teklifi taleplerinizi yanıtlamak","Yedek parça siparişinizin faturasını düzenlemek, ödemenizi doğrulamak ve parçayı belirttiğiniz adrese göndermek","Talebinizin durumu değiştiğinde uygulama bildirimi göndermek","Ayrıca izin verirseniz, kampanya ve duyurularımızı uygulama bildirimiyle iletmek"]},{"baslik":"Hukuki sebep nedir?","paragraflar":["Verileriniz KVKK’nın 5. maddesinde sayılan şu sebeplere dayanılarak işlenir:"],"maddeler":["Bir sözleşmenin kurulması veya ifasıyla doğrudan ilgili olması (satış sonrası hizmet ve garanti) — md. 5/2-c","Veri sorumlusunun hukuki yükümlülüğünü yerine getirmesi (garanti, tüketici ve vergi mevzuatı; fatura düzenleme yükümlülüğü) — md. 5/2-ç","İlgili kişinin temel hak ve özgürlüklerine zarar vermemek kaydıyla meşru menfaat — md. 5/2-f","Yetkili bayi ve servislere aktarım ile açıkça rıza verdiğiniz işlemler için açık rızanız — md. 5/1"]},{"baslik":"Kimlere aktarılıyor?","paragraflar":["Talebinizi karşılayabilmek için gerektiği kadarıyla, size en yakın yetkili bayi ve yetkili servise aktarılabilir. Örneğin servis talebinizde adınız, telefonunuz ve makinenizin seri numarası ilgili servise iletilir.","Bunun dışında, kanunen yetkili kamu kurum ve kuruluşlarına mevzuatın gerektirdiği hâllerde aktarım yapılabilir.","Verileriniz pazarlama amacıyla üçüncü kişilere satılmaz veya kiralanmaz."]},{"baslik":"Nasıl topluyoruz?","paragraflar":["Verileriniz, uygulamaya kendiniz yazdığınız bilgiler üzerinden elektronik ortamda toplanır. Uygulama, siz girmediğiniz hiçbir bilgiyi kendiliğinden toplamaz.","Anlık konumunuz yalnızca siz \"Konumumu kullan\" düğmesine bastığınızda alınır, yalnızca en yakın bayiyi sıralamak için telefonunuzun içinde kullanılır ve hiçbir yere gönderilmez.","Cihaz bildirim kimliği yalnızca uygulama bildirimlerine izin verdiğinizde oluşur. İzni telefonunuzun ayarlarından dilediğiniz zaman kapatabilirsiniz; kapattığınızda bildirim gönderilemez."]},{"baslik":"Ne kadar süre saklanıyor?","paragraflar":["Verileriniz, satış sonrası hizmet ilişkisi sürdüğü ve ilgili mevzuatın öngördüğü zamanaşımı süreleri boyunca saklanır. Sürenin sonunda silinir, yok edilir veya anonim hâle getirilir."]},{"baslik":"Haklarınız neler?","paragraflar":["KVKK’nın 11. maddesi uyarınca şunları talep edebilirsiniz:"],"maddeler":["Kişisel verinizin işlenip işlenmediğini öğrenme, işlenmişse bilgi talep etme","İşlenme amacını ve amacına uygun kullanılıp kullanılmadığını öğrenme","Yurt içinde veya yurt dışında aktarıldığı üçüncü kişileri bilme","Eksik veya yanlış işlenmişse düzeltilmesini isteme","Şartları oluştuğunda silinmesini veya yok edilmesini isteme","Düzeltme ve silme işlemlerinin aktarıldığı üçüncü kişilere bildirilmesini isteme","Yalnızca otomatik sistemlerle analiz edilmesi sonucu aleyhinize bir sonuç çıkmasına itiraz etme","Kanuna aykırı işlenmesi sebebiyle zarara uğrarsanız zararın giderilmesini talep etme"]},{"baslik":"Nasıl başvurursunuz?","paragraflar":["Yukarıdaki haklarınız için paksan@paksanmakina.com.tr adresine yazabilirsiniz. Başvurunuz en geç 30 gün içinde sonuçlandırılır.","Hesabınızın ve kayıtlarınızın tamamen silinmesini istiyorsanız da aynı adrese yazmanız yeterli; işlem PAKSAN tarafından yapılır."]}]}', 0xD86B46BA71FB08B71096268961264C3AE006E3613272A3602FF6F1F53B215BA2, 1, N'2026-08-14'),
        (N'ticariIleti', N'1.0', N'en', N'Campaign and Announcement Notifications', N'{"kisaAd":"Campaign Notifications","onayCumlesi":"I would like to receive campaign, announcement and new product notifications through the app. (Optional)","bolumler":[{"baslik":"What do we send?","paragraflar":["If you allow it, we send notifications to your phone through the app about new product announcements, seasonal campaigns, dealer events and spare part offers."]},{"baslik":"This permission is not required","paragraflar":["You can use the app fully without giving this permission. Machine registration, breakdown support, service and spare part requests all work independently of it.","Service notifications — the status of your request, or a safety warning about your machine — do not count as campaign notifications; they are sent independently of this permission."]},{"baslik":"You can turn it off any time","paragraflar":["You can turn this permission on and off with a single tap on the Profile page in the app. If you prefer, you can also withdraw it by writing to paksan@paksanmakina.com.tr. You can also switch off all notifications from the app in your phone settings."]}],"ustNot":"This is an English translation provided for convenience. The binding text is the Turkish original, prepared under Turkish Personal Data Protection Law No. 6698 (KVKK)."}', 0xE2547319874ABED97729BCC609860A84C545B5C1C7167C482AD2BDA816D75E53, 0, N'2026-08-14'),
        (N'ticariIleti', N'1.0', N'tr', N'Kampanya ve Duyuru Bildirimleri', N'{"kisaAd":"Kampanya Bildirimleri Metni","onayCumlesi":"Kampanya, duyuru ve yeni ürün bildirimlerinin uygulama üzerinden bana gönderilmesini istiyorum. (İsteğe bağlı)","bolumler":[{"baslik":"Ne gönderiyoruz?","paragraflar":["İzin verirseniz; yeni ürün duyuruları, sezon kampanyaları, bayi etkinlikleri ve yedek parça fırsatları hakkındaki bildirimleri uygulama üzerinden telefonunuza gönderiyoruz."]},{"baslik":"Bu izin zorunlu değil","paragraflar":["Bu izni vermeseniz de uygulamayı eksiksiz kullanabilirsiniz. Makine kaydı, arıza desteği, servis ve yedek parça talepleri bu izinden bağımsız çalışır.","Talebinizin durumu veya makinenizle ilgili güvenlik uyarısı gibi hizmete ilişkin bildirimler kampanya bildirimi sayılmaz; onlar bu izinden bağımsız olarak gönderilir."]},{"baslik":"İstediğiniz zaman kapatabilirsiniz","paragraflar":["Bu izni uygulamanın Profil sayfasından tek dokunuşla açıp kapatabilirsiniz. İsterseniz paksan@paksanmakina.com.tr adresine yazarak da geri alabilirsiniz. Ayrıca telefonunuzun ayarlarından uygulamanın tüm bildirimlerini kapatabilirsiniz."]}]}', 0x485DD09C796005F7EB9FC8F02A26607E3CCC4C2D661B66FC31B98C23E48133C6, 1, N'2026-08-14')
    ) AS v (MetinKodu, Surum, DilKodu, Baslik, IcerikJson, IcerikOzeti, AsilMetin, MetinTarihi)
) AS k
WHERE NOT EXISTS (SELECT 1 FROM kvkk.MetinSurumu AS h WHERE h.MetinKodu = k.MetinKodu AND h.Surum = k.Surum AND h.DilKodu = k.DilKodu);
